package com.vitalvetcris.app;
import android.app.*; import android.content.*; import androidx.core.app.NotificationCompat;
public class ReminderReceiver extends BroadcastReceiver {@Override public void onReceive(Context context,Intent intent){Intent open=context.getPackageManager().getLaunchIntentForPackage(context.getPackageName());PendingIntent pi=PendingIntent.getActivity(context,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new NotificationCompat.Builder(context,MainActivity.CHANNEL_ID).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(intent.getStringExtra("title")).setContentText(intent.getStringExtra("body")).setStyle(new NotificationCompat.BigTextStyle().bigText(intent.getStringExtra("body"))).setPriority(NotificationCompat.PRIORITY_HIGH).setAutoCancel(true).setContentIntent(pi).build();((NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE)).notify((int)System.currentTimeMillis(),n);}}
